import{_ as i,l,o as e,c as s,v as t,p as d,x as r,d as n,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"IRDS 路线图","description":"","frontmatter":{"title":"IRDS 路线图","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/irds-roadmap.md","filePath":"litho/irds-roadmap.md","lastUpdated":1789023840000}'),D={name:"litho/irds-roadmap.md"};function c(S,a,m,E,_,I){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="irds-路线图" tabindex="-1">IRDS 路线图 <a class="header-anchor" href="#irds-路线图" aria-label="Permalink to &quot;IRDS 路线图&quot;">​</a></h1><div class="epigraph"><p>ITRS 停更之后，IRDS 用器件与系统视角列光刻需求：它是共识表，不是某厂承诺，更不是物理定律。</p><footer>—— 对照 IEEE IRDS（International Roadmap for Devices and Systems）及其 Lithography 章节的定位</footer></div><p><a href="/litho/transistor-density-metric">上一课</a>统一了密度口径。缺口是行业共识表从哪来。本课钉 IRDS。表上的层成本如何落到晶圆，留给[下一课](/litho/cost-per-layer-wafer）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IRDS 继承 ITRS 的「需求表」角色：未来节点的节距、套刻、CDU、EUV/DUV 选项、计量。用途：设备与材料供应商对齐研发，不是代工厂的 PDK。读表时要看年份与「要求 vs 已知解」。把 IRDS 行当成 ASML 出货计划，会错。</p><p>缺口是<strong>共识需求 vs 交付</strong>，不是再争节点名。表中的 overlay/CD 预算结构可与掩模 CDU 课对照，数值仍随版次变，课文不抄死表。</p><h3 id="与-dtco-的关系" tabindex="-1">与 DTCO 的关系 <a class="header-anchor" href="#与-dtco-的关系" aria-label="Permalink to &quot;与 DTCO 的关系&quot;">​</a></h3><p>IRDS 给行业边界；DTCO 在某厂机台集合内选点。厂可以比表激进或保守。光刻课程用 IRDS 当对照骨架，用厂公开路径当实例，二者标注来源。</p><p><span class="marginnote">IRDS 含 More than Moore、封装、光子。后课替代形态会回到这些章，本课先钉：它不是只服务逻辑 CMOS 平面缩。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读 Lithography 章：关键层半节距、多重 vs EUV、计量缺口。对照自己的 CPP/MMP。缺口表（没有已知解的红格）才是研究课题，不是已量产。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>路线图是委员会博弈后的需求投影，受物理（随机、DOF）与工业（单一来源）约束。它滞后或超前于某厂都正常。物理极限课将与表中 Hyper-NA 之后的红格对照。</p>',13)),(e(),d(p,null,{default:r(()=>[h(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRDS%5B%22IRDS%20%E9%9C%80%E6%B1%82%E8%A1%A8%22%5D%20--%3E%20IND%5B%22%E8%AE%BE%E5%A4%87%E6%9D%90%E6%96%99%E5%AF%B9%E9%BD%90%22%5D%0A%20%20FAB%5B%22%E4%BB%A3%E5%B7%A5%20DTCO%22%5D%20--%3E%20PDK%5B%22%E5%8F%AF%E4%BA%A4%E4%BB%98%20PDK%22%5D%0A%20%20IRDS%20-.-%3E%7C%22%E5%AF%B9%E7%85%A7%22%7C%20FAB%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某年版数值当 2026 永远有效。不发明 IRDS 未写的 arXiv。IRDS 不报价。</p><p>后课默认：行业需求有公开表；下一课把需求翻译成每层与每晶圆成本结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IRDS 是共识需求路线，不是厂承诺或物理定律。</li><li>读「要求 vs 已知解」；红格才是研究。</li><li>与 DTCO 对照使用，不互相替代。</li><li>出处：IEEE IRDS Lithography 章节定位。</li></ul>',5))])}const u=i(D,[["render",c]]);export{R as __pageData,u as default};
